import { existsSync, readFileSync, unlinkSync } from "node:fs";
import { spawnSync } from "node:child_process";

// Vinext and Next write different route definitions into the same generated
// directory. A Next validator left behind by a previous build cannot validate
// Vinext's module. Remove only this obsolete generated file; Next regenerates
// its validator on its next build, where full route validation still runs.
const routes = ".next/types/routes.d.ts";
const validator = ".next/types/validator.ts";
if (
  existsSync(routes) &&
  existsSync(validator) &&
  readFileSync(routes, "utf8").startsWith(
    "// This file is generated by vinext.",
  ) &&
  readFileSync(validator, "utf8").startsWith(
    "// This file is generated automatically by Next.js",
  )
) {
  unlinkSync(validator);
}
const result = spawnSync(
  process.execPath,
  ["node_modules/typescript/bin/tsc", "--noEmit"],
  { stdio: "inherit" },
);
if (result.error) throw result.error;
process.exit(result.status ?? 1);
